INSERT INTO public.purchase_invoice_dispatches
  (company_id, electronic_invoice_id, supplier_vat, supplier_name, invoice_number, invoice_date, document_type,
   net_amount, total_amount, file_period, sent_by, sent_at, source_file, notes)
SELECT '00000000-0000-0000-0000-000000000001', ei.id, s.piva, s.nome, s.nr, s.data_doc, coalesce(ei.tipo_documento, 'TD01'),
       s.imp, s.tot, DATE '2026-09-01', 'manuale_studio', NULL, 'FattureAcquisto_Settembre_2026.xlsx',
       'Consegnata da Sabrina nel file di settembre 2026 (Fattura SMART, protocollo ' || s.prot || ' del ' || to_char(s.data_reg::date, 'DD/MM/YYYY') || ').'
FROM s
LEFT JOIN LATERAL (
  SELECT e.id, e.tipo_documento FROM public.electronic_invoices e
  WHERE e.company_id = '00000000-0000-0000-0000-000000000001'
    AND regexp_replace(upper(coalesce(e.supplier_vat,'')), '^IT', '') = regexp_replace(upper(s.piva), '^IT', '')
    AND ltrim(regexp_replace(upper(e.invoice_number), '[^0-9A-Z]', '', 'g'), '0') = ltrim(regexp_replace(upper(s.nr), '[^0-9A-Z]', '', 'g'), '0')
  ORDER BY (e.invoice_date = s.data_doc) DESC, e.created_at
  LIMIT 1
) ei ON true
ON CONFLICT DO NOTHING;
